import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { ICON_GLYPHS } from "../design/iconGlyphs.ts";
// The generator itself (plain JavaScript): its vocabulary and the functions that turn a source into path data.
import { ICONS, NF_DIR, glyphFromSvg, inputsHash } from "../../scripts/build-icons.mjs";

/**
 * The icon system (components/Icon over design/iconGlyphs.ts, generated by `npm run build:icons`): the generated
 * file matches its sources, every glyph sits on the 24 grid, every name the app passes exists, and the icon
 * font is gone.
 */

const SRC = join(dirname(fileURLToPath(import.meta.url)), "..");
const GENERATED = join(SRC, "design", "iconGlyphs.ts");
const names = Object.keys(ICON_GLYPHS);

function sourceFiles(dir: string, out: string[] = []): string[] {
  for (const f of readdirSync(dir)) {
    const p = join(dir, f);
    if (statSync(p).isDirectory()) sourceFiles(p, out);
    else if (/\.tsx?$/.test(f) && !f.endsWith(".test.ts") && p !== GENERATED) out.push(p);
  }
  return out;
}
const files = sourceFiles(SRC).map((path) => ({ path: path.slice(SRC.length + 1), text: readFileSync(path, "utf8") }));

test("the generated module is up to date with the generator and the glyph sources", () => {
  const header = /Inputs ([0-9a-f]{16})\./.exec(readFileSync(GENERATED, "utf8"));
  assert.ok(header, "iconGlyphs.ts has no inputs line");
  assert.equal(header[1], inputsHash(), "stale: run `npm run build:icons` in mobile/");
  assert.deepEqual(names, Object.keys(ICONS).sort(), "the generated names are the generator's vocabulary");
});

test("each NoteFusion glyph is drawn exactly from its SVG source", () => {
  for (const [name, source] of Object.entries(ICONS as Record<string, string>)) {
    if (!source.startsWith("nf:")) continue;
    const svg = readFileSync(join(NF_DIR, source.slice(3) + ".svg"), "utf8");
    assert.deepEqual({ ...ICON_GLYPHS[name as keyof typeof ICON_GLYPHS] }, glyphFromSvg(svg), name);
  }
});

/** Every point a path's commands land on, in absolute coordinates (control points are not walked). */
function endpoints(d: string): [number, number][] {
  const out: [number, number][] = [];
  let i = 0;
  let cmd = "";
  let x = 0, y = 0, sx = 0, sy = 0;
  const skip = () => {
    while (i < d.length && /[\s,]/.test(d[i]!)) i++;
  };
  const num = () => {
    skip();
    const m = /^-?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?/i.exec(d.slice(i));
    if (!m) throw new Error(`a number expected at ${i} in ${d}`);
    i += m[0].length;
    return +m[0];
  };
  const flag = () => {
    skip();
    const c = d[i++];
    if (c !== "0" && c !== "1") throw new Error(`an arc flag expected in ${d}`);
    return +c;
  };
  for (;;) {
    skip();
    if (i >= d.length) break;
    if (/[a-z]/i.test(d[i]!)) cmd = d[i++]!;
    else if (!cmd) throw new Error(`no command before ${d.slice(i, i + 8)}`);
    const rel = cmd !== cmd.toUpperCase();
    const at = (nx: number, ny: number) => {
      x = rel ? x + nx : nx;
      y = rel ? y + ny : ny;
      out.push([x, y]);
    };
    switch (cmd.toUpperCase()) {
      case "M":
        at(num(), num());
        [sx, sy] = [x, y];
        cmd = rel ? "l" : "L";
        break;
      case "L":
      case "T":
        at(num(), num());
        break;
      case "H":
        x = rel ? x + num() : num();
        out.push([x, y]);
        break;
      case "V":
        y = rel ? y + num() : num();
        out.push([x, y]);
        break;
      case "C":
        num(), num(), num(), num();
        at(num(), num());
        break;
      case "S":
      case "Q":
        num(), num();
        at(num(), num());
        break;
      case "A":
        num(), num(), num(), flag(), flag();
        at(num(), num());
        break;
      case "Z":
        [x, y] = [sx, sy];
        cmd = "";
        break;
      default:
        throw new Error(`unknown command ${cmd}`);
    }
  }
  return out;
}

test("every glyph sits on the 24 grid", () => {
  for (const name of names) {
    const g = ICON_GLYPHS[name as keyof typeof ICON_GLYPHS];
    for (const d of [g.s, g.k, g.w]) {
      if (!d) continue;
      const pts = endpoints(d);
      assert.ok(pts.length > 0, name);
      for (const [px, py] of pts) {
        assert.ok(px >= -0.01 && px <= 24.01 && py >= -0.01 && py <= 24.01, `${name}: (${px}, ${py}) is off the grid`);
      }
    }
  }
});

test("every icon name the app passes (props, data tables, <Icon name>) exists", () => {
  const used = new Set<string>();
  // The quoted names in an expression, leaving out what a condition compares against (`v.id === "bars" ? …`).
  const literals = (expr: string) =>
    [...expr.replace(/[!=]==?\s*["'][^"']*["']/g, "").matchAll(/["']([a-z0-9-]+)["']/g)].map((m) => m[1]!);
  for (const { path, text } of files) {
    const sites = [
      ...text.matchAll(/<Icon\b[^>]*?\bname=(\{[^}]*\}|"[^"]*"|'[^']*')/g),
      // An assignment or a property (`icon="…"`, `icon: "…"`, `icon={a ? "…" : "…"}`), never a comparison.
      ...text.matchAll(/\b(?:icon|emptyIcon|pillIcon)\s*(?:=(?!=)|:)\s*(\{[^}\n]*\}?|"[^"]*"|'[^']*'|[^,\n}]*)/g),
    ];
    for (const m of sites) {
      for (const name of literals(m[1]!)) {
        assert.ok(name in ICON_GLYPHS, `${path}: "${name}" is not an icon (scripts/build-icons.mjs ICONS)`);
        used.add(name);
      }
    }
  }
  assert.ok(used.size > 90, `only ${used.size} icon names found: the scan has stopped seeing them`);
});

test("only the icons the app uses are generated", () => {
  const all = files.map((f) => f.text).join("\n");
  const unused = names.filter((n) => !all.includes(`"${n}"`) && !all.includes(`'${n}'`));
  assert.deepEqual(unused, [], "remove them from ICONS in scripts/build-icons.mjs and rebuild");
});

test("no source file uses the icon font", () => {
  for (const { path, text } of [...files, { path: "App.tsx", text: readFileSync(join(SRC, "..", "App.tsx"), "utf8") }]) {
    if (path === join("design", "icons.ts")) continue; // the unused Icons8 map, only a comment mentions Ionicons
    assert.ok(!/@expo\/vector-icons|\bIonicons\b/.test(text), `${path} still uses Ionicons`);
  }
});

test("the icon ink exists in Day and Night, and Night's Pro gold is not the problem amber", () => {
  const theme = readFileSync(join(SRC, "design", "theme.ts"), "utf8");
  const block = (start: string) => theme.slice(theme.indexOf(start), theme.indexOf("};", theme.indexOf(start)));
  const value = (b: string, token: string) => new RegExp(`\\n\\s*${token}: "(#[0-9A-F]{6})"`, "i").exec(b)?.[1];
  for (const b of [block("export const colors = {"), block("export const darkColors: Palette = {")]) {
    assert.match(value(b, "icon") ?? "", /^#[0-9A-F]{6}$/i);
    assert.notEqual(value(b, "premium")?.toUpperCase(), value(b, "warning")?.toUpperCase());
  }
});
